import { create } from 'zustand'
import { api, type Message, type Session, type StreamEvent, type ToolCallInfo } from '@/lib/api'

/** 当前活跃的 AbortController，用于中断流式请求。 */
let _abortController: AbortController | null = null

/** 前端会话类型（兼容 name/title）。 */
export interface SessionItem {
  id: string
  title: string
  created_at: string
  updated_at: string
  archived_at: string | null
  message_count: number
}

interface ChatState {
  sessions: SessionItem[]
  currentSessionId: string | null
  messages: Message[]
  isStreaming: boolean
  searchQuery: string

  // Actions
  loadSessions: () => Promise<void>
  createSession: () => Promise<string>
  switchSession: (id: string) => Promise<void>
  deleteSession: (id: string) => Promise<void>
  renameSession: (id: string, title: string) => Promise<void>
  archiveSession: (id: string) => Promise<void>
  forkSession: (id: string, messageId?: number) => Promise<string>
  sendMessage: (content: string) => Promise<void>
  abortStreaming: () => void
  setSearchQuery: (query: string) => void
  clearMessages: () => void
  submitFeedback: (messageId: number, rating: 'like' | 'dislike', comment?: string) => Promise<void>
  deleteFeedback: (messageId: number) => Promise<void>
  toggleBookmark: (messageId: number) => void
}

/** 从后端 Session 映射到前端 SessionItem。 */
function toSessionItem(s: Session): SessionItem {
  return {
    id: s.id,
    title: s.title || s.name || '新会话',
    created_at: s.created_at,
    updated_at: s.updated_at,
    archived_at: s.archived_at ?? null,
    message_count: s.message_count ?? 0,
  }
}

export const useChatStore = create<ChatState>((set, get) => ({
  sessions: [],
  currentSessionId: null,
  messages: [],
  isStreaming: false,
  searchQuery: '',

  abortStreaming: () => {
    _abortController?.abort()
    _abortController = null
  },

  loadSessions: async () => {
    try {
      const raw = await api.getSessions()
      set({ sessions: raw.map(toSessionItem) })
    } catch { /* ignore */ }
  },

  createSession: async () => {
    const raw = await api.createSession()
    const item = toSessionItem(raw)
    set((s) => ({
      sessions: [item, ...s.sessions],
      currentSessionId: item.id,
      messages: [],
    }))
    return item.id
  },

  switchSession: async (id: string) => {
    set({ currentSessionId: id, messages: [] })
    try {
      const raw = await api.getMessages(id)
      // 将 conversations 表记录转为 Message 格式
      const mapped: Message[] = (raw as unknown as Record<string, unknown>[]).map((m) => {
        // 解析 metadata（存储 tool_calls）
        let tool_calls: ToolCallInfo[] | undefined
        const metaStr = m.metadata as string | undefined
        if (metaStr) {
          try {
            tool_calls = JSON.parse(metaStr) as ToolCallInfo[]
          } catch { /* ignore */ }
        }
        return {
          id: Number(m.id ?? 0),
          role: (m.direction === 'in' ? 'user' : 'assistant') as Message['role'],
          content: String(m.text ?? m.content ?? ''),
          thinking: (m.thinking as string) || undefined,
          tool_calls,
          created_at: String(m.timestamp ?? m.created_at ?? ''),
        }
      }).filter(m => m.content || m.thinking) // 过滤空消息
      set({ messages: mapped })

      // 加载该会话的反馈数据
      try {
        const feedbackList = await api.getSessionFeedback(id)
        if (feedbackList.length > 0) {
          const feedbackMap = new Map(feedbackList.map(f => [f.message_id, f]))
          set((s) => ({
            messages: s.messages.map((msg) => {
              const fb = feedbackMap.get(msg.id)
              if (fb && fb.rating) {
                return { ...msg, feedback: { rating: fb.rating as 'like' | 'dislike', comment: fb.comment } }
              }
              return msg
            }),
          }))
        }
      } catch { /* 反馈加载失败不影响消息显示 */ }
    } catch (e) {
      console.error('加载消息失败:', e)
      set({ messages: [] })
    }
  },

  deleteSession: async (id: string) => {
    await api.deleteSession(id)
    const { currentSessionId, sessions } = get()
    const filtered = sessions.filter((s) => s.id !== id)
    set({ sessions: filtered })
    if (currentSessionId === id) {
      if (filtered.length > 0) {
        await get().switchSession(filtered[0].id)
      } else {
        set({ currentSessionId: null, messages: [] })
      }
    }
  },

  renameSession: async (id: string, title: string) => {
    try {
      await api.renameSession(id, title)
      set((s) => ({
        sessions: s.sessions.map((sess) =>
          sess.id === id ? { ...sess, title } : sess,
        ),
      }))
    } catch { /* ignore */ }
  },

  archiveSession: async (id: string) => {
    try {
      await api.archiveSession(id)
      // 从列表中移除（归档后不再显示在活跃列表）
      set((s) => ({
        sessions: s.sessions.filter((sess) => sess.id !== id),
      }))
      const { currentSessionId } = get()
      if (currentSessionId === id) {
        const remaining = get().sessions
        if (remaining.length > 0) {
          await get().switchSession(remaining[0].id)
        } else {
          set({ currentSessionId: null, messages: [] })
        }
      }
    } catch { /* ignore */ }
  },

  forkSession: async (id: string, messageId?: number) => {
    const raw = await api.forkSession(id, messageId)
    const item = toSessionItem(raw)
    set((s) => ({
      sessions: [item, ...s.sessions],
      currentSessionId: item.id,
      messages: [],
    }))
    return item.id
  },

  sendMessage: async (content: string) => {
    const { currentSessionId } = get()
    let sessionId = currentSessionId

    // Auto-create session if needed
    if (!sessionId) {
      sessionId = await get().createSession()
    }

    // Add user message optimistically
    const userMsg: Message = {
      id: Date.now(),
      role: 'user',
      content,
      created_at: new Date().toISOString(),
    }
    set((s) => ({ messages: [...s.messages, userMsg], isStreaming: true }))

    // Add placeholder assistant message
    const assistantMsg: Message = {
      id: Date.now() + 1,
      role: 'assistant',
      content: '',
      created_at: new Date().toISOString(),
    }
    set((s) => ({ messages: [...s.messages, assistantMsg] }))

    try {
      _abortController = new AbortController()
      let accumulated = ''
      let thinkingAccumulated = ''
      let currentToolCall: ToolCallInfo | null = null
      const toolCalls: ToolCallInfo[] = []

      // 流式节流：参考 deepseek-harness animation-frame 策略
      // delta/reasoning 事件累积到局部变量，通过 rAF 批量 flush
      let pendingContent = ''
      let pendingThinking = ''
      let rafId: number | null = null

      const flushPending = () => {
        rafId = null
        if (!pendingContent && !pendingThinking) return
        const contentToAdd = pendingContent
        const thinkingToAdd = pendingThinking
        pendingContent = ''
        pendingThinking = ''
        accumulated += contentToAdd
        thinkingAccumulated += thinkingToAdd
        set((s) => {
          const msgs = [...s.messages]
          const last = msgs[msgs.length - 1]
          if (last && last.role === 'assistant') {
            msgs[msgs.length - 1] = { ...last, content: accumulated, thinking: thinkingAccumulated }
          }
          return { messages: msgs }
        })
      }

      const scheduleFlush = () => {
        if (rafId === null) {
          rafId = requestAnimationFrame(flushPending)
        }
      }

      // 工具事件立即 flush（用户需要即时看到工具状态）
      const flushToolUpdate = () => {
        // 先 flush 待处理的文本
        if (rafId !== null) {
          cancelAnimationFrame(rafId)
          rafId = null
        }
        flushPending()
        set((s) => {
          const msgs = [...s.messages]
          const last = msgs[msgs.length - 1]
          if (last && last.role === 'assistant') {
            msgs[msgs.length - 1] = { ...last, tool_calls: [...toolCalls] }
          }
          return { messages: msgs }
        })
      }

      for await (const event of api.chatStream(content, sessionId, _abortController.signal)) {
        const ev = event as StreamEvent
        switch (ev.type) {
          case 'delta':
            if (ev.content) {
              pendingContent += ev.content
              scheduleFlush()
            }
            break
          case 'reasoning':
            if (ev.content) {
              pendingThinking += ev.content
              scheduleFlush()
            }
            break
          case 'tool_call': {
            const tc: ToolCallInfo = {
              id: ev.tool_id || '',
              name: ev.tool_name || '',
              args: ev.tool_args,
              status: 'running',
              started_at: new Date().toISOString(),
            }
            toolCalls.push(tc)
            currentToolCall = tc
            flushToolUpdate()
            break
          }
          case 'tool_result':
            if (currentToolCall) {
              currentToolCall.result = ev.tool_result
              currentToolCall.success = ev.success
              currentToolCall.status = ev.success ? 'completed' : 'error'
              currentToolCall.completed_at = new Date().toISOString()
              currentToolCall = null
              flushToolUpdate()
            }
            break
          case 'done': {
            const elapsed = ev.elapsed_ms
            if (elapsed != null) {
              set((s) => {
                const msgs = [...s.messages]
                const last = msgs[msgs.length - 1]
                if (last && last.role === 'assistant') {
                  msgs[msgs.length - 1] = { ...last, elapsed_ms: elapsed }
                }
                return { messages: msgs }
              })
            }
            break
          }
        }
      }

      // 最终 flush 确保所有待处理内容都已渲染
      if (rafId !== null) {
        cancelAnimationFrame(rafId)
        rafId = null
      }
      flushPending()
    } catch (err: unknown) {
      // Abort 不触发 fallback，保留已生成内容
      if (err instanceof DOMException && err.name === 'AbortError') {
        // 已在 finally 中统一处理
      } else {
        // Fallback to non-streaming
        try {
          const resp = await api.chat(content, sessionId)
          set((s) => {
            const msgs = [...s.messages]
            const last = msgs[msgs.length - 1]
            if (last && last.role === 'assistant') {
              msgs[msgs.length - 1] = { ...last, content: resp.reply }
            }
            return { messages: msgs }
          })
        } catch {
          set((s) => {
            const msgs = [...s.messages]
            const last = msgs[msgs.length - 1]
            if (last && last.role === 'assistant') {
              msgs[msgs.length - 1] = { ...last, content: '抱歉，发生了错误，请重试。' }
            }
            return { messages: msgs }
          })
        }
      }
    } finally {
      _abortController = null
      set({ isStreaming: false })
      // 流式完成后刷新会话列表（标题可能已更新）
      get().loadSessions()
    }
  },

  setSearchQuery: (query: string) => set({ searchQuery: query }),

  clearMessages: () => set({ messages: [], currentSessionId: null }),

  submitFeedback: async (messageId: number, rating: 'like' | 'dislike', comment?: string) => {
    const { currentSessionId } = get()
    if (!currentSessionId) return
    try {
      await api.submitFeedback(messageId, currentSessionId, rating, comment)
      set((s) => ({
        messages: s.messages.map((msg) =>
          msg.id === messageId
            ? { ...msg, feedback: { rating, comment } }
            : msg
        ),
      }))
    } catch (e) {
      console.error('提交反馈失败:', e)
    }
  },

  deleteFeedback: async (messageId: number) => {
    try {
      await api.deleteFeedback(messageId)
      set((s) => ({
        messages: s.messages.map((msg) =>
          msg.id === messageId
            ? { ...msg, feedback: undefined }
            : msg
        ),
      }))
    } catch (e) {
      console.error('删除反馈失败:', e)
    }
  },

  toggleBookmark: (messageId: number) => {
    set((s) => ({
      messages: s.messages.map((msg) =>
        msg.id === messageId
          ? { ...msg, bookmarked: !msg.bookmarked }
          : msg
      ),
    }))
  },
}))
